  label: string;
  value: string;
  change: number;
  /** For metrics where a decrease is good (e.g. churn). */
  invertGood?: boolean;
  caption: string;
  icon: LucideIcon;
};

const KPIS: Kpi[] = [
  {
    id: "revenue",
    label: "Total revenue",
    value: "$48,290",
